Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define LL long long
#define ULL unsigned LL
#define PII pair<int,int>
#define PB push_back
#define MP make_pair
#define INF 1000000000
#define MOD 1000000007

int shortestDist[15][15][15][15];
int capacity[400][400];
char scienceMap[20][20];
char reactionMap[20][20];
int deltaX[] = {1, 0, -1, 0};
int deltaY[] = {0, 1, 0, -1};
int currentIter = 3;
int visitedNodes[400];

int nSize, maxTime;
int augmentFlow(int current, int target, int flow) {
    if (current == target) return flow;
    if (visitedNodes[current] == currentIter) return 0;
    visitedNodes[current] = currentIter;
    for (int i = 0; i <= target; i++) {
        if (capacity[current][i] > 0) {
            int pushed = augmentFlow(i, target, min(flow, capacity[current][i]));
            if (pushed > 0) {
                capacity[current][i] -= pushed;
                capacity[i][current] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int nodeID(int x, int y) {
    return (x - 1) * nSize + y - 1;
}

int reachability[13][13], tempReach[13][13];

void propagate(int val) {
    for (int i = 1; i <= nSize; i++)
        for (int j = 1; j <= nSize; j++)
            tempReach[i][j] = reachability[i][j];

    for (int i = 1; i <= nSize; i++) {
        for (int j = 1; j <= nSize; j++) {
            if (tempReach[i][j] == val) {
                for (int dir = 0; dir < 4; dir++) {
                    int ni = i + deltaX[dir], nj = j + deltaY[dir];
                    if (ni > 0 && nj > 0 && ni <= nSize && nj <= nSize && tempReach[ni][nj] < val && scienceMap[ni][nj] != 'Y') {
                        reachability[ni][nj] = val;
                    }
                }
            }
        }
    }
}

bool isReachable(int sx, int sy, int tx, int ty, int ix, int iy) {
    memset(reachability, 0, sizeof(reachability));
    reachability[sx][sy] = 1;
    reachability[ix][iy] = 2;
    for (int i = 0; i < 100; i++) {
        propagate(1);
        if (reachability[tx][ty] == 1) return true;
        propagate(2);
        if (reachability[tx][ty] == 2) return false;
    }
    return false;
}

int main() {
    int infX, infY;
    memset(shortestDist, 1, sizeof(shortestDist));
    cin >> nSize >> maxTime;
    for (int i = 1; i <= nSize; i++) {
        scanf(" %s", scienceMap[i] + 1);
        for (int j = 1; j <= nSize; j++) {
            shortestDist[i][j][i][j] = 0;
            if (scienceMap[i][j] == 'Z') {
                infX = i; infY = j;
            }
        }
    }
    for (int i = 1; i <= nSize; i++) {
        scanf(" %s", reactionMap[i] + 1);
    }
    for (int i = 1; i <= nSize; i++) {
        for (int j = 1; j <= nSize; j++) {
            for (int dir = 0; dir < 4; dir++) {
                int ni = i + deltaX[dir], nj = j + deltaY[dir];
                if (ni > 0 && ni <= nSize && nj > 0 && nj <= nSize) {
                    if (scienceMap[i][j] != 'Y' && scienceMap[ni][nj] != 'Y') {
                        shortestDist[i][j][ni][nj] = 1;
                    }
                }
            }
        }
    }
    for (int ki = 1; ki <= nSize; ki++) {
        for (int kj = 1; kj <= nSize; kj++) {
            for (int ii = 1; ii <= nSize; ii++) {
                for (int ij = 1; ij <= nSize; ij++) {
                    for (int ji = 1; ji <= nSize; ji++) {
                        for (int jj = 1; jj <= nSize; jj++) {
                            shortestDist[ii][ij][ji][jj] = min(
                                shortestDist[ii][ij][ji][jj],
                                shortestDist[ii][ij][ki][kj] + shortestDist[ki][kj][ji][jj]
                            );
                        }
                    }
                }
            }
        }
    }
    int sourceNode = nSize * nSize * 2 + 1;
    int sinkNode = nSize * nSize * 2 + 2;
    for (int i = 1; i <= nSize; i++) {
        for (int j = 1; j <= nSize; j++) {
            if (isdigit(scienceMap[i][j])) {
                capacity[sourceNode][nodeID(i, j)] = scienceMap[i][j] - '0';
            }
            if (isdigit(reactionMap[i][j])) {
                capacity[nSize * nSize + nodeID(i, j)][sinkNode] = reactionMap[i][j] - '0';
            }
            if (isdigit(scienceMap[i][j])) {
                for (int ki = 1; ki <= nSize; ki++) {
                    for (int kj = 1; kj <= nSize; kj++) {
                        if (scienceMap[i][j] > '0' && reactionMap[ki][kj] > '0') {
                            if (isdigit(reactionMap[ki][kj]) && shortestDist[i][j][ki][kj] <= maxTime && isReachable(i, j, ki, kj, infX, infY)) {
                                capacity[nodeID(i, j)][nSize * nSize + nodeID(ki, kj)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }
    int totalFlow = 0, flowVal;
    while ((flowVal = augmentFlow(sourceNode, sinkNode, 1000)) > 0) {
        totalFlow += flowVal;
        currentIter++;
    }
    cout << totalFlow << endl;
    return 0;
}
